<?php
declare(strict_types=1);
namespace App\Services; use App\Core\Session; use App\Repositories\UserRepository;
final class AuthService { public function login(string $email,string $password,bool $remember=false):bool{$repo=new UserRepository();$u=$repo->findByEmail($email);if(!$u||$u['status']!=='active'||!password_verify($password,$u['password_hash']))return false;Session::regenerate();$full=$repo->findWithRole((int)$u['id']);Session::put('user_id',(int)$u['id']);Session::put('user',$full);Session::put('permissions',$full['permissions']??[]);Session::put('remember',$remember);return true;} public function register(array $data):bool|string{$name=trim((string)($data['name']??''));$email=trim((string)($data['email']??''));$password=(string)($data['password']??'');$confirm=(string)($data['password_confirmation']??'');if($name===''||$email===''||$password==='')return 'Please fill in all required fields.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))return 'Please enter a valid email address.';if(strlen($password)<6)return 'Password must be at least 6 characters.';if($password!==$confirm)return 'Passwords do not match.';$repo=new UserRepository();if($repo->findByEmail($email))return 'An account with this email already exists.';$id=$repo->create(['name'=>$name,'email'=>$email,'password'=>$password,'status'=>'active']);$roleId=$repo->roleIdByName('User');if($roleId)$repo->setRole($id,$roleId);$this->login($email,$password);return true;} public function logout():void{Session::destroy();}}
